# -*- coding: utf-8 -*-
# Contenido de las diapositivas de punto (JD00-JD08) y del guion. HTML directo (comillas tipográficas).
VIDEO = '@isarojasmx (Isa Rojas), «El Nuevo Testamento a examen, Cap. 8: ¿Jesús dijo que era Dios?» (7 min 21 s)'

POINTS = []

POINTS.append(dict(
 id='JD01', tag='Punto 1 · 0:40–1:17', title='«Yo y el Padre somos uno» (Jn 10:30) y el Salmo 82',
 ref='El vídeo: «es una unidad de propósito, no de esencia»; Jesús «cita el Salmo 82 y baja el tono de la acusación»',
 says='«Yo y el Padre somos uno». «Siete capítulos después Jesús dice por sus discípulos: para que todos sean uno, así como nosotros somos uno» (Jn 17:21). «Si ser uno con el Padre convierte a alguien en Dios, los discípulos también lo serían.» Y ante la acusación de blasfemia «Jesús no responde sí, soy Dios: cita el Salmo 82 […] bajando el tono de la acusación».',
 conc='«Uno» (<i>hén</i>, neutro) no significa por sí solo «una persona», y Jn 17:21 usa la misma palabra para los discípulos. Brown (1965, p. 566, n. 52) reconoce que en Jn 10:33 ss. Jesús «no da una afirmación clara» a la acusación de hacerse Dios.',
 resp=[
  'Lo que decide el sentido es el contexto que el propio Juan registra: los oyentes entienden «tú, siendo hombre, te haces Dios» (10:33) y toman piedras (10:31). Jesús no corrige esa lectura: argumenta de lo menor a lo mayor (10:34-36), repite «el Padre está en mí y yo en el Padre» (10:38) y ellos «procuraban de nuevo prenderle» (10:39).',
  'Jn 17:21 dice «en nosotros»: los discípulos son uno <i>participando</i> en la unidad del Padre y el Hijo («como tú, Padre, en mí y yo en ti»). La comparación toma a Padre e Hijo como modelo, no como equivalentes de los discípulos.',
  'Brown, en la misma nota (n. 52, <b>BR</b>): Juan «hace explícito lo que estaba implícito en el ministerio de Jesús». Conviene decir lo que ese «implícito» no es: Brown no dice que Jesús afirmara «soy Dios».',
 ],
 syl=('Si una frase se tomó en su tiempo como pretensión de igualdad con Dios, y quien la dijo no retiró ese sentido sino que lo argumentó, el texto la presenta como tal pretensión.',
      'En Jn 10:30-39 los oyentes entienden «te haces Dios» (v. 33), Jesús apela a su unión con el Padre (v. 38) y no retira la frase; los oyentes siguen intentando prenderle (v. 39).',
      'Jn 10:30 no se explica en el texto como mera «unidad de propósito»: se presenta como una unión con el Padre que sus oyentes tomaron por pretensión divina. (Esto es lo que dice el texto de Juan; que Jesús lo dijera históricamente es otra discusión: véase JD07.)'),
 srcs='Jn 10:30-39 y 17:21-23 (texto bíblico). Brown, «Does the New Testament Call Jesus God?», <i>Theological Studies</i> 26 (1965) 566 n. 52 (leído en el PDF abierto de la revista).',
))

POINTS.append(dict(
 id='JD02', tag='Punto 2 · 1:17–1:39', title='«Antes que Abraham fuese, yo soy» (Jn 8:58) frente a Jn 9:9',
 ref='El vídeo: el ciego sanado dice «ego eimi» y «nadie lo considera Dios»; existir en el plan de Dios (Jer 1:5) tampoco hace Dios',
 says='«Se dice: “yo soy” sería el nombre de Dios de Éxodo. Pero en Juan 9:9 el ciego sanado dice exactamente lo mismo en griego, <i>ego eimi</i>, y nadie lo considera Dios.» «Que alguien existiera en el plan de Dios antes de nacer tampoco lo convierte en Dios: a Jeremías Dios le dice “antes que te formase en el vientre te conocí”.»',
 conc='<i>Egó eimi</i> es una expresión corriente en griego: en 9:9 es «yo soy [el que se sentaba y mendigaba]». No todos los «yo soy» de Juan son el nombre divino, y Jer 1:5 habla de un conocimiento de Dios, no de una existencia propia del profeta.',
 resp=[
  'En 9:9 hay un predicado sobreentendido (la pregunta es «¿no es este el que se sentaba y mendigaba?») y nadie reacciona. En 8:58 no hay predicado, la frase contrasta <i>genésthai</i> («llegar a ser», Abraham) con <i>eimí</i> («soy», Jesús), y la reacción es inmediata: «tomaron piedras para arrojárselas» (8:59). Es el texto el que marca la diferencia.',
  'Jer 1:5 dice «<i>yo</i> te conocí»: Dios es el sujeto que conoce. Jesús dice «<i>yo soy</i>»: él es el sujeto que existe. No es la misma forma de frase.',
  'En Jn 8:24 y 8:28 («si no creéis que <i>yo soy</i>, moriréis en vuestros pecados») y 13:19 el «yo soy» va sin predicado y como objeto de fe; el eco habitual es Is 43:10 (LXX <i>egó eimi</i>). Brown trata el uso absoluto en el Apéndice IV de su comentario (<i>Anchor Bible</i>, Juan): <b>no pude leer ese apéndice</b>, así que no lo cito.',
 ],
 syl=('Una misma expresión cambia de significado según su contexto: predicado, contraste y reacción de los oyentes.',
      'En Jn 9:9 el contexto (predicado sobreentendido, ninguna reacción) la hace ordinaria; en Jn 8:58-59 el contexto (sin predicado, contraste con «llegar a ser», apedreamiento) la presenta como pretensión de un modo de ser distinto al de Abraham.',
      'El ejemplo de 9:9 no neutraliza 8:58: muestra que <i>egó eimi</i> puede ser ordinaria, no que lo sea en todos los casos. (Que el Jesús histórico dijera 8:58 es discutido: Hurtado y Ehrman lo niegan; véase JD07.)'),
 srcs='Jn 8:24, 28, 58-59; 9:9; 13:19; Is 43:10; Jer 1:5 (texto bíblico). Brown, <i>Theological Studies</i> 26 (1965) 566 n. 52 cita «5:18; 7:58-59; 10:30-33» (así impreso; probablemente 8:58-59) como «el problema de Dios» en Juan.',
))

POINTS.append(dict(
 id='JD03', tag='Punto 3 · 1:39–2:25', title='Apocalipsis: «Alfa y Omega», «rey de reyes» y «mi Dios»',
 ref='El vídeo: Ap 1:11 «no está en los manuscritos más antiguos»; en 1:8 habla el Padre; compartir un título no hace Dios (Dn 2:37); Jesús dice «mi Dios» (Ap 3:12). Rótulo en pantalla: «Ap 1:8, 11 y 22:13» (pero 22:13 no se comenta)',
 says='«Esa frase no está en los manuscritos más antiguos, ni en el Sinaítico ni en el Alejandrino, y el <i>Pulpit Commentary</i> dice que debe omitirse. Segundo, en 1:8 los mejores manuscritos dicen “dice el Señor Dios”. […] Compartir un título no hace a nadie Dios: Daniel le dice a Nabucodonosor “tú, oh rey, eres rey de reyes”, y el Jesús del Apocalipsis dice cuatro veces “mi Dios” en un solo versículo.»',
 conc='En Ap 1:11 la cláusula «Yo soy el Alfa y la Omega, el primero y el último» falta en el Sinaítico (transcripción de codexsinaiticus.org, no comparé el facsímil) y las ediciones críticas la omiten (Nestle 1904 en Biblehub; no pude ver el aparato de NA28). En 1:8 habla «el Señor Dios, el que es y era y ha de venir», que es normalmente el Padre. Y en 3:12 el Resucitado dice «mi Dios».',
 resp=[
  'La duda textual afecta a 1:11, no a los demás lugares. En el Sinaítico (transcripción) aparecen «Yo soy el primero y el último» (1:17; lo dice el Resucitado: «estuve muerto», 1:18), «el primero y el último, el que estuvo muerto y revivió» (2:8) y «Yo soy el Alfa y la Omega, el primero y el último, el principio y el fin» (22:13), dicho por Jesús («vengo pronto», 22:12; «Yo, Jesús», 22:16). El vídeo rotula 22:13 y no lo contesta.',
  '«El primero y el último» no es un título honorífico como «rey de reyes»: es una autodefinición exclusiva de YHWH, «yo soy el primero y yo soy el último, y fuera de mí no hay dios» (Is 44:6; 48:12). Nabucodonosor es «rey de reyes» porque «el Dios del cielo te ha dado el reino» (Dn 2:37): título recibido, no exclusivo.',
  'Bauckham (<i>The Theology of the Book of Revelation</i>, Cambridge 1993, cap. «The Lamb on the Throne»): «“Yo soy el primero y el último” corresponde a la autodeclaración divina “Yo soy el Alfa y la Omega”», y en el conjunto de Apocalipsis hay un patrón de dos autodeclaraciones de Dios y dos de Cristo (texto del resumen del capítulo en Cambridge Core; <b>no vi la página del libro</b>).',
  '«Mi Dios» (3:12) es lo que el Resucitado dice del Padre, igual que en Jn 20:17: nadie niega la distinción Padre–Hijo; la cuestión es de qué lado de la distinción Creador/criatura sitúa el libro a Jesús, y Ap 5:13 le da, junto al que está en el trono, la alabanza de toda la creación (Bauckham, Georgetown 2018, p. 13: <b>BK</b>).',
 ],
 syl=('Un título compartido solo prueba identidad cuando es un título exclusivo del Dios único.',
      '«El primero y el último» es exclusivo de YHWH (Is 44:6; 48:12: «fuera de mí no hay dios») y Ap 1:17; 2:8; 22:13 lo aplican a Jesús, con independencia de la variante de 1:11. «Rey de reyes» (Dn 2:37) es un título recibido y no exclusivo.',
      'Apocalipsis aplica a Jesús un título exclusivo de YHWH; la comparación con «rey de reyes» no vale. (El argumento no depende de Ap 1:8 ni de 1:11.)'),
 srcs='Ap 1:8, 11, 17-18; 2:8; 3:12; 5:13; 21:6; 22:12-16; Is 44:6; 48:12; Dn 2:37. Sinaítico: codexsinaiticus.org (transcripción, no facsímil); Nestle 1904 en biblehub.com/multi/revelation/1-11.htm. Bauckham 1993: Cambridge Core. No obtuve el Alejandrino, NA28 ni Metzger.',
))

POINTS.append(dict(
 id='JD04', tag='Punto 4 · 2:25–3:13', title='Tomás (Jn 20:28) y Raymond Brown',
 ref='El vídeo: Brown dice que «Jesús nunca se aplicó el título “Dios” a sí mismo» y que solo una vez alguien se lo aplica (Tomás); Jn 20:17 y 20:31',
 says='«Dice Raymond Brown: el título “Dios” sería ciertamente característico, pero Jesús nunca se lo aplicó a sí mismo y en los relatos evangélicos solamente una vez alguien se lo aplica a él en forma afirmativa. Una sola vez en cuatro evangelios, no lo dice Jesús sino Tomás.» Además Jn 20:17 («mi Dios») y Jn 20:31 («para que creáis que Jesús es el Cristo, el Hijo de Dios»).',
 conc='Brown lo dice, y se lee en la <b>p. 84 de la edición castellana</b> (el vídeo la enseña, con el subrayado). En el original inglés (Paulist, 1994, Apéndice III) dice: «The title “God” would be truly distinctive; but Jesus never uses it of himself and only once is it given affirmatively to him by someone else in the Gospel narrative». En los Sinópticos Jesús nunca es llamado «Dios» (Brown 1965, p. 566: <b>BR</b>).',
 resp=[
  'La frase de Brown trata del <b>título</b> «Dios» (<i>theós</i>), no de si Jesús se presenta en términos divinos. En su artículo de 1965 Brown responde «afirmativamente» a la pregunta «¿Llama el NT Dios a Jesús?»: «en tres casos claros y en cinco con cierta probabilidad», y Jn 20:28 es «el ejemplo más claro» (p. 565).',
  'Sobre <i>kyrios</i>, el vídeo dice que Brown «aclara que significa señor, dueño». En 1965 Brown escribe que «Jesús es Señor» era una fórmula popular y que con ella los cristianos dieron a Jesús el título <i>kyrios</i>, «la traducción estándar de YHWH en la LXX» (p. 566); y en la n. 60 sostiene que, en general, los autores del NT sabían que daban a Jesús un título que en la LXX designaba al Dios de Israel.',
  'Hurtado (<i>NIDB</i>, «Christology»): «los casos inequívocos [de <i>theós</i> aplicado a Jesús] están en Juan 1:1 y 20:28». Jn 20:28 es además el final del Evangelio: Brown lo describe como el punto donde «uno de ellos expresa por fin una fe adecuada en Jesús» (p. 565).',
  'Límites que conviene decir: Brown cree que la fórmula de 20:28 podría ser «una fórmula de confesión de la época del evangelista» y que «no hay razón para pensar que Jesús fuera llamado Dios en las capas más antiguas» del NT (p. 567). Es decir: el título explícito es tardío; la discusión de fondo es si la identidad divina estaba ya implícita (JD07).',
 ],
 syl=('Que alguien no use un título no implica que no se presente en términos que ese título expresa.',
      'Brown distingue el título «Dios» del contenido: afirma que el NT llama Dios a Jesús (3+5 casos), que le da <i>kyrios</i> (título de YHWH en la LXX) y que Juan «hace explícito lo implícito» en el ministerio de Jesús.',
      'Citar a Brown para negar la identidad divina de Jesús confunde «no usó el título» con «no hay pretensión de identidad»; Brown sostiene lo primero para los Sinópticos y lo segundo no lo sostiene.'),
 srcs='Brown, «Does the New Testament Call Jesus God?», <i>Theological Studies</i> 26 (1965) 564-567 (PDF abierto, páginas reproducidas en BR); Brown, <i>An Introduction to New Testament Christology</i> (Paulist 1994) en el original inglés, leído solo en fragmentos; ed. castellana (Sígueme), p. 84, vista en el fotograma del vídeo. Hurtado, «Christology» (<i>NIDB</i>), PDF de la web del autor (páginas reproducidas en HU).',
))

POINTS.append(dict(
 id='JD05', tag='Punto 5 · 3:13–3:31', title='Perdonar pecados: Mc 2:5-7, Mt 9:8 y Jn 20:23',
 ref='El vídeo: Mt 9:8 dice que Dios «había dado tal potestad a los hombres»; en Jn 20:23 Jesús se la da a los discípulos',
 says='«Los escribas dicen: ¿quién puede perdonar pecados sino solo Dios? Pero Mateo, al contar la misma escena, termina así: “la multitud glorificó a Dios que había dado tal potestad a los hombres”. Es una potestad que Dios da: en Juan 20:23 Jesús también se la da a los discípulos.»',
 conc='Mt 9:8 dice «a los hombres» y Jn 20:23 transmite a los discípulos la potestad de perdonar. Boyarin, el estudioso que más defiende el carácter divino-humano del «Hijo del hombre», precisa que esa autoridad es «obviamente delegada por Dios» (ensayo de 2010, <b>BO</b>).',
 resp=[
  'En Mc 2:5 Jesús dice «tus pecados te son perdonados» sin decir «Dios te perdona». Compárese a Natán: «YHWH ha remitido tu pecado» (2 Sm 12:13). Los escribas lo oyen como invasión de una prerrogativa de Dios («¿quién puede perdonar pecados sino solo Dios?», 2:7) y lo llaman blasfemia.',
  'Jesús no responde que el principio sea falso: lo valida con una señal. «Para que sepáis que el Hijo del hombre tiene autoridad en la tierra para perdonar pecados», y cura al paralítico (2:10-11). Es decir, acepta el criterio de los escribas y reclama cumplirlo.',
  'En Jn 20:22-23 los discípulos reciben el Espíritu <i>antes</i> de perdonar: la potestad les viene dada, mientras que en Mc 2:5 Jesús la ejerce sin remitir a nadie que se la dé. Mt 9:8 muestra que la multitud ve esa autoridad como venida de Dios, lo que encaja con Dn 7:13-14: el «hijo de hombre» recibe de Dios «dominio, gloria y reino».',
  'Boyarin: una vez excluido que «el Hijo del hombre» sea otra forma de decir «yo», «debe concederse que aquí es un título»; ese título es el del redentor «divino-humano» de Daniel 7 (ensayo de 2010; texto visto solo en una reproducción por blog). Wright incluye el perdón de pecados entre los gestos de un caso acumulativo y escribe que, por sí solos, ninguno sería concluyente: «siguen siendo crípticos».',
 ],
 syl=('Si una acción es presentada por el texto como prerrogativa exclusiva de Dios, quien la ejerce en su propio nombre reclama una posición que el texto reserva a Dios, aunque indique que la ejerce por delegación.',
      'Mc 2:5-10 presenta el perdón como prerrogativa de Dios (v. 7), Jesús lo declara en su propio nombre (v. 5) y lo valida con una señal (v. 10-11) sin corregir el principio.',
      'Mc 2:1-12 presenta a Jesús ejerciendo una prerrogativa divina; el matiz «autoridad delegada» (Mt 9:8; Boyarin) precisa el modo, no suprime la pretensión.'),
 srcs='Mc 2:1-12; Mt 9:1-8; Jn 20:21-23; 2 Sm 12:13; Dn 7:13-14. Boyarin, «The Sovereignty of the Son of Man: Reading Mark 2» (2010), vía reproducción en vridar.org (páginas 354 y 361 según el bloguero). Wright, «Jesus and the Identity of God» (Ex Auditu 14, 1998), ntwrightpage.com.',
))

POINTS.append(dict(
 id='JD06', tag='Punto 6 · 3:31–4:22', title='«Señor del sábado», «Hijo del hombre» y <i>kyrios</i>',
 ref='El vídeo: el sábado «fue hecho para el ser humano, no de una naturaleza divina»; «Hijo del hombre» es como Dios llama a Ezequiel (más de 90 veces); <i>kyrios</i> = señor, dueño',
 says='«“El día de reposo fue hecho por causa del hombre, por tanto el Hijo del hombre es Señor aun del día de reposo”: saca la conclusión de que el sábado fue hecho para el ser humano, no de una naturaleza divina. Para defenderse Jesús no dice “porque soy Dios”. […] “Hijo del hombre” es como Dios llama más de 90 veces al profeta Ezequiel, y sobre la palabra <i>kyrios</i> el mismo Brown aclara que significa señor, dueño, no Dios.»',
 conc='Jesús argumenta con el ejemplo de David (Mc 2:25-26), no con un «soy Dios». «Hijo de hombre» (<i>ben adam</i>) es, en efecto, la forma en que Ezequiel es llamado. Y Hurtado concede que en la mayoría de los usos de dirección en los Evangelios <i>kyrios</i> es «señor» en sentido corriente.',
 resp=[
  '«El Hijo del hombre» con artículo, en boca de Jesús y con autoridad (Mc 2:10, 28) o «viniendo con las nubes» (Mc 14:62), remite a Dn 7:13, no al vocativo de Ezequiel. Hurtado: la expresión «probablemente refleja un rasgo distintivo del propio habla de Jesús» (<i>NIDB</i>); Boyarin: era «el nombre que esos judíos usaban para su esperado redentor divino-humano» (2010, p. 354 según el bloguero).',
  'Ser «señor del sábado» es autoridad sobre lo que la Ley llama «sábado para YHWH tu Dios» (Ex 20:10). Boyarin pone aquí un límite honesto: «el Hijo del hombre, habiéndosele dado dominio en el ámbito humano, es el Señor del sábado».',
  'Sobre <i>kyrios</i>, Brown no dice que signifique siempre «solo señor»: para la fórmula «Jesús es Señor» dice que era «la traducción estándar de YHWH en la LXX» (1965, p. 566). Hurtado: los usos escatológicos de «Señor» para Jesús «probablemente connotaban mucho más que “amo”»: «a Jesús se le atribuyó el papel escatológico y los atributos de Yahvé» (<i>NIDB</i>).',
 ],
 syl=('El sentido de un título en boca de alguien se determina por la tradición a la que remite, no por otra tradición homónima.',
      'En Ez «hijo de hombre» es un vocativo dirigido al profeta; en los Evangelios es «el Hijo del hombre», con artículo, con autoridad y con «las nubes del cielo» (Dn 7:13), y Hurtado lo considera un rasgo del habla de Jesús.',
      'Reducir el título al uso de Ezequiel no explica sus rasgos en los Evangelios; la lectura de Dn 7 los explica mejor. (Vermes discute este uso y Boyarin le contesta: «no hay evidencia» de que fuera un circunloquio por «yo».)'),
 srcs='Mc 2:23-28; Ex 20:10; Ez 2:1 ss.; Dn 7:13-14. Brown 1965 p. 566 (BR). Hurtado, «Christology» (<i>NIDB</i>), PDF de la web del autor. Boyarin 2010, vía vridar.org.',
))

POINTS.append(dict(
 id='JD07', tag='Punto 7 · 4:22–6:23', title='«Veredicto de los académicos»: qué dicen de verdad Dunn, Vermes, Ehrman, Brown y Pitre',
 ref='El vídeo: «amplio consenso académico» en que el Jesús histórico «no se presentó a sí mismo en términos divinos»',
 says='«¿Acaso solo es una lectura musulmana? Vamos a escuchar a los especialistas.» Dunn: «no podemos afirmar que Jesús creyera que él era el Hijo de Dios encarnado». Vermes: «la religión de Jesús era totalmente teocéntrica». Ehrman: «Jesús no se declaró a sí mismo Dios». Brown (ya visto). Pitre «reconoce» que «para la investigación contemporánea sobre Jesús en su conjunto la respuesta es un rotundo no».',
 conc='<b>Sí hay un amplio acuerdo en una cosa:</b> que el Jesús histórico no dijo en términos explícitos «soy Dios». Lo dicen Dunn, Ehrman (NPR, 2014: «durante su vida Jesús mismo no se llamó Dios»), Vermes, Casey, Hurtado (blog, 2017) y Brown (para el título). Pitre lo reconoce en el pasaje que enseña el vídeo.',
 resp=[
  '<b>Dunn.</b> En la página que enseña el vídeo la frase destacada acaba en un punto y coma. Sigue (lo leí en el fotograma): «pero podemos afirmar que la enseñanza en ese sentido, tal como se expresó en el pensamiento cristiano de finales del siglo I, fue, a la luz de todo el acontecimiento de Cristo, una reflexión adecuada y una elaboración del propio sentido de filiación y de misión escatológica de Jesús». Y la frase anterior de la misma página dice que una «conciencia de autoridad divina, de intimidad única en su relación con Dios» se detecta «en el estrato más antiguo y probablemente auténtico de la tradición evangélica».',
  '<b>Vermes.</b> Lo que enseña el vídeo no es una página de Vermes sino una reseña de su libro <i>Christian Beginnings</i>. La frase «esa idea no deja rastro en los sinópticos y solo aparece en algunos pasajes de Juan» es de <b>Renan</b> (<i>Vida de Jesús</i>, 1863; texto en Gutenberg), no de Vermes; y Renan añade en el mismo capítulo que Jesús «se cree más que un hombre ordinario, pero separado de Dios por una distancia infinita».',
  '<b>Ehrman.</b> Pitre lo cita (<i>How Jesus Became God</i>) diciendo: «La idea de que Jesús es Dios […] fue la visión de los primeros cristianos muy poco después de la muerte de Jesús» (CLJ, captura en PI). Ehrman niega que Jesús lo dijera; no niega que muy pronto se creyera.',
  '<b>Pitre.</b> El párrafo del «rotundo no» es la <i>descripción</i> de la investigación que su artículo (CLJ, 4 feb. 2025) va a discutir. Inmediatamente después (mismo artículo) viene «La cristología más temprana era una cristología alta» (Fredriksen, Ehrman, Chester, Allison, Bauckham, Hurtado) y su tesis: «la mejor explicación […] es que Jesús mismo habló y actuó como si fuera divino […] de una manera muy judía». Su propia nota 26 cita dos capítulos del <i>Handbook</i> (Broadhead, «Implicit Christology and the Historical Jesus»; Kreplin) sobre las pretensiones mesiánicas de Jesús: <b>«no discute el tema» es la valoración de Pitre sobre pretensiones divinas, no sobre el libro entero</b>.',
 ],
 syl=('Un acuerdo en que Jesús no dijo explícitamente «soy Dios» no equivale a un acuerdo en que no se presentó en términos divinos de modo implícito, ni en que la creencia en su divinidad surgiera tarde.',
      'Los propios estudiosos citados aceptan una autoridad o filiación única (Dunn), la afirmación neotestamentaria «Jesús es Dios» (Brown 1965) o una cristología alta muy temprana (Ehrman, Fredriksen, Allison, Bauckham, Hurtado, según Pitre); y otros sostienen que Jesús la reclamó de forma implícita (Wright, Bird, Evans, Pitre).',
      'Del «consenso» citado solo se sigue que Jesús no usó la fórmula explícita; no se sigue que «nunca reclamó lo que no le pertenecía». La cuestión histórica sigue abierta y dividida (HU frente a WR, PI, BI).'),
 srcs='Dunn: fotograma del vídeo (4:31), edición y página sin comprobar (Pitre cita la 2.ª ed., p. 254). Vermes/Renan: Gutenberg #16581; reseña citada por Pitre (p. 60). Ehrman: NPR 7-4-2014 y CLJ. Pitre: Church Life Journal, 4-2-2025 (página web, captura en PI); <i>Jesus and Divine Christology</i>, Eerdmans 2024. <i>Handbook</i>: ARCE (índice).',
))

POINTS.append(dict(
 id='JD08', tag='Punto 8 · 6:23–7:21', title='«Se esperaría una declaración clara»',
 ref='El vídeo: «saber quién es Dios es saber a quién debes adorar […] mínimo se esperaría una declaración clara»; «Jesús nunca reclamó lo que no le pertenecía»',
 says='«Saber quién es Dios es saber a quién debes de adorar, y de eso depende la salvación eterna de una persona, pues mínimo se esperaría una declaración clara. Los evangelios leídos con honestidad y la investigación académica dicen lo mismo: Jesús nunca reclamó lo que no le pertenecía. […] ¿Por qué si Jesús nunca se atribuyó a sí mismo ser Dios, por qué tú sí se lo atribuyes?»',
 conc='Es verdad que en los Sinópticos Jesús no dice «soy Dios, adórenme»; y que Hurtado y Brown (para el título «Dios») piensan que la formulación explícita viene después de la Pascua. Eso hay que decirlo sin rodeos.',
 resp=[
  'Un judío del siglo I no formularía así una pretensión sobre su relación con Dios. Pitre: Jesús habría reclamado ser divino «de una manera muy judía, con acertijos, preguntas y alusiones a la Escritura, para revelar y a la vez ocultar el secreto de su divinidad». Wright: «el lenguaje era profundamente cifrado, pero la acción simbólica no lo era»; Jesús viene a Sión «haciendo lo que YHWH había prometido hacer». Bird: Jesús «se creía encarnando la persona misma de Dios en su misión» (WR, PI, BI).',
  'Los Evangelios narran la reacción de sus oyentes (si esas escenas son históricas es, de nuevo, lo discutido): acusación de «hacerse igual a Dios» (Jn 5:18; 10:33), blasfemia ante el sumo sacerdote tras «Yo soy, y veréis al Hijo del hombre sentado a la diestra del Poder y viniendo con las nubes» (Mc 14:62-64; Dn 7:13; Sal 110:1). Bird: «en el juicio, lo más probable es que dijera algo en el sentido de que creía ser la figura de Dn 7:13-14 y estar legítimamente entronizado junto a Dios» (BI). Segal lo dice con cautela: «puede que se asociara con el “hijo del hombre” de Dn 7» (solo vía blog).',
  'La adoración a Jesús es muy temprana y dentro del monoteísmo judío: «adorar a Jesús no infringía el monoteísmo judío, porque Jesús mismo pertenecía a la identidad única del único Dios» (Bauckham, p. 13: BK); Plinio, hacia 112: los cristianos recitan un himno «a Cristo como a un dios» (<i>carmenque Christo quasi deo dicere</i>, Cartas X, 96.7; Platner 1894, p. 91). Hurtado (citado por Pitre): la devoción a Jesús como divino «brotó de repente y deprisa, no de forma gradual y tardía».',
  'Honestidad: el paso de «hay indicios implícitos» a «Jesús lo reclamó» es la parte discutida. Hurtado dice que el análisis crítico «no ofrece evidencia» de que Jesús afirmara compartir la gloria divina (blog, 2017); Wright niega que Jesús «supiera que era Dios» como se sabe que se está cansado. Los que sí lo defienden (Wright, Pitre, Bird, Evans) lo hacen con matices.',
 ],
 syl=('Si en el judaísmo del siglo I una pretensión de identidad divina se expresa con acciones y alusiones a las Escrituras, la ausencia de una fórmula explícita no refuta la pretensión.',
      'Las fuentes registran acciones y alusiones de ese tipo (Mc 2:5-10; 14:62; Jn 8:58) y la reacción de acusación de blasfemia (Mc 14:63-64; Jn 10:33), y los primeros cristianos adoran a Jesús sin romper su monoteísmo.',
      '«No hay frase explícita» no equivale a «Jesús no reclamó». (La premisa histórica —que esas acciones y alusiones sean de Jesús y se entendieran así— es la que discuten Hurtado, Dunn y Ehrman.)'),
 srcs='Pitre, CLJ 4-2-2025; Wright, <i>Ex Auditu</i> 14 (1998), ntwrightpage.com; Bird en <i>How God Became Jesus</i> (Zondervan 2014, extracto en zondervanacademic.com); Segal, <i>Two Powers in Heaven</i> (1977), solo vía blog; Bauckham, Georgetown 2018, p. 13; Plinio, <i>Epistulae</i> X, 96, ed. Platner (1894) p. 91 (imagen de página leída); Hurtado, blog 9-10-2017.',
))
